class AudioManager {
  constructor(){let saved={};try{saved=JSON.parse(localStorage.getItem('blackout.audio')||'{}')||{};}catch{}this.musicVolume=this.validVolume(saved.musicVolume,.35);this.sfxVolume=this.validVolume(saved.sfxVolume,.70);this.muted=typeof saved.muted==='boolean'?saved.muted:false;this.enabled=false;this.music=null;this.ambience=null;this.cache=new Map();this.activeSfx=new Set();}
  validVolume(value,fallback){const number=Number(value);return Number.isFinite(number)&&number>=0&&number<=1?number:fallback;}
  unlock(){this.enabled=true;}
  persist(){localStorage.setItem('blackout.audio',JSON.stringify({musicVolume:this.musicVolume,sfxVolume:this.sfxVolume,muted:this.muted}));}
  effectiveSfxVolume(){return this.muted?0:this.sfxVolume*SFX_MASTER_GAIN;}
  syncActiveSfxVolume(){const volume=this.effectiveSfxVolume();this.activeSfx.forEach(sound=>{sound.volume=volume;});}
  sfx(name){if(!this.enabled||this.muted||!SFX[name])return;let base=this.cache.get(name);if(!base){base=new Audio(SFX[name]);base.preload='metadata';this.cache.set(name,base);}const sound=base.cloneNode();sound.volume=this.effectiveSfxVolume();this.activeSfx.add(sound);const release=()=>this.activeSfx.delete(sound);sound.addEventListener('ended',release,{once:true});sound.addEventListener('error',release,{once:true});sound.play().catch(release);}
  playLoop(channel,name,volumeScale=1){if(channel==='music')name='exploration';if(!this.enabled||!AUDIO_TRACKS[name])return;const current=this[channel];if(current?.dataset.track===name)return;this.stopLoop(channel);const track=new Audio(AUDIO_TRACKS[name]);track.dataset.track=name;track.dataset.channel=channel;track.dataset.scale=String(volumeScale);track.loop=true;track.preload='none';track.volume=0;this[channel]=track;track.play().then(()=>this.fade(track,this.targetVolume(track))).catch(()=>{});}
  targetVolume(track){const baseGain=BACKGROUND_TRACK_GAINS[track?.dataset.track]??1;return this.muted?0:baseGain*this.musicVolume*Number(track?.dataset.scale||1);}
  fade(track,target){clearInterval(track.fadeTimer);track.fadeTimer=setInterval(()=>{const difference=target-track.volume;if(Math.abs(difference)<.025){track.volume=target;clearInterval(track.fadeTimer);return;}track.volume=Math.max(0,Math.min(1,track.volume+Math.sign(difference)*.02));},40);}
  stopLoop(channel){const track=this[channel];if(!track)return;clearInterval(track.fadeTimer);track.pause();this[channel]=null;}
  setMusicVolume(value){this.musicVolume=this.validVolume(value,.35);for(const track of [this.music,this.ambience])if(track)this.fade(track,this.targetVolume(track));this.persist();}
  setSfxVolume(value){this.sfxVolume=this.validVolume(value,.70);this.syncActiveSfxVolume();this.persist();}
  toggleMute(){this.muted=!this.muted;for(const track of [this.music,this.ambience])if(track)this.fade(track,this.targetVolume(track));this.syncActiveSfxVolume();this.persist();return this.muted;}
}
