function createMissionIntro(title,description,objective='',compact=false){const panel=document.createElement('section');panel.className=`mission-intro-panel${compact?' mission-intro-compact':''}`;const heading=document.createElement('h2'),copy=document.createElement('p');heading.textContent=title;copy.textContent=description;panel.append(heading,copy);if(objective){const objectivePanel=document.createElement('div'),label=document.createElement('span'),text=document.createElement('strong');label.textContent='NEXT OBJECTIVE';text.textContent=objective;objectivePanel.className='mission-intro-objective';objectivePanel.append(label,text);panel.append(objectivePanel);}return panel;}
function artComposition(src,alt=''){const frame=document.createElement('div');frame.className='art-composition';const image=document.createElement('img');image.className='art-screen';image.src=src;image.alt=alt;image.draggable=false;frame.append(image);return frame;}
function preloadImage(src){if(imagePreloadCache.has(src))return imagePreloadCache.get(src);const promise=new Promise(resolve=>{const image=new Image();image.onload=resolve;image.onerror=resolve;image.src=src;});imagePreloadCache.set(src,promise);return promise;}
function preloadImages(sources){return Promise.all([...new Set(sources)].map(preloadImage));}
function preloadFirstMissionAssets(){if(firstMissionPreloadPromise)return firstMissionPreloadPromise;const hudImage=hud.querySelector(':scope > img'),hudSource=hudImage.dataset.src||ASSETS.hud;if(!hudImage.getAttribute('src'))hudImage.src=hudSource;firstMissionPreloadPromise=Promise.all([ASSETS.home,hudSource,ASSETS.life,ASSETS.phone,ASSETS.emergencyConnection,NIGHTFALL_COLLECTIBLES.medallion.asset].map(preloadImage));return firstMissionPreloadPromise;}
function preloadFirstQuestionPanel(){if(!firstQuestionPreloadPromise)firstQuestionPreloadPromise=preloadImage(ASSETS.question);return firstQuestionPreloadPromise;}
function clearScreen(){clearTimeout(transitionId);clearInterval(radioDriftId);clearInterval(transmissionCountdownId);if(tunnelRun?.raf)cancelAnimationFrame(tunnelRun.raf);tunnelRun=null;radioDriftId=0;transmissionCountdownId=0;hud.classList.remove('route-screen-hud');screen.replaceChildren();screen.className='screen';screen.style.backgroundImage='';}
function showFeedback(text,type='info',duration=1200){clearTimeout(feedbackId);feedback.textContent=text;feedback.className=`feedback ${type} show`;feedbackId=setTimeout(()=>feedback.className='feedback',duration);}
function showNightfallNotice(unlocked=false,persistent=false){screen.querySelector('.nightfall-notice')?.remove();const notice=document.createElement('div'),messages=['','This may be connected to the blackout...',"The evidence is connected to the city's power network.",'The blackout may not be accidental.','Project Nightfall is connected to the failures across the city.','The truth is hidden in the Project Nightfall files.'];notice.className=`nightfall-notice${unlocked?' nightfall-unlocked':''}`;notice.innerHTML=`<strong>${state.secrets===5?'EVIDENCE COMPLETE':'PROJECT NIGHTFALL EVIDENCE RECOVERED'}</strong><span>${state.secrets}/5 EVIDENCE ITEMS</span><span>${messages[state.secrets]}</span>`;screen.append(notice);requestAnimationFrame(()=>notice.classList.add('show'));if(!persistent)setTimeout(()=>{notice.classList.remove('show');setTimeout(()=>notice.remove(),250);},READABLE_MESSAGE_DURATION);}
function collectNightfallSecret(element,id){if(element.disabled||state.collectedSecrets.includes(id))return;element.disabled=true;if(id==='medallion')screen.querySelector('.first-secret-hint')?.remove();state.collectedSecrets=[...new Set([...state.collectedSecrets,id])];state.secrets=Math.min(NIGHTFALL_COLLECTIBLE_ORDER.length,state.collectedSecrets.length);updateHud();audio.sfx('secretFound');element.classList.add('collected');if(state.secrets===NIGHTFALL_COLLECTIBLE_ORDER.length){setTimeout(()=>audio.sfx('nightfallUnlock'),350);showNightfallNotice(true);if(state.game===12&&state.game12Completed.length===4)transitionId=setTimeout(showFinalAuthorization,READABLE_MESSAGE_DURATION);}else showNightfallNotice();setTimeout(()=>element.remove(),650);}
function addNightfallCollectible(container,id,context=''){const collectible=NIGHTFALL_COLLECTIBLES[id];if(!collectible||state.collectedSecrets.includes(id)||container.querySelector(`.nightfall-${id}`))return;if(!context){const currentIndex=NIGHTFALL_COLLECTIBLE_ORDER.indexOf(id),missingEarlier=NIGHTFALL_COLLECTIBLE_ORDER.slice(0,currentIndex).filter(secretId=>!state.collectedSecrets.includes(secretId));missingEarlier.forEach((secretId,index)=>addNightfallCollectible(container,secretId,`nightfall-fallback nightfall-carry carry-${index+1} carry-at-${id}`));}const element=document.createElement('button');element.type='button';element.className=`nightfall-collectible nightfall-${id}${context?` ${context}`:''}`;element.setAttribute('aria-label',`Collect ${collectible.name}`);element.innerHTML=`<span class="nightfall-sparks" aria-hidden="true"><i></i><i></i><i></i><i></i></span><img src="${collectible.asset}" alt="${collectible.name}">`;element.onclick=()=>collectNightfallSecret(element,id);container.append(element);if(id==='medallion'&&container===screen&&!context){const hint=document.createElement('div');hint.className='first-secret-hint';hint.textContent='Pick this up first';container.append(hint);}}
function showTooltip(anchor,text){clearTimeout(tooltipId);anchor.parentElement.querySelectorAll('.button-tooltip').forEach(item=>item.remove());const tip=document.createElement('div');tip.className='button-tooltip';tip.textContent=text;tip.style.left=`${anchor.offsetLeft+anchor.offsetWidth/2}px`;tip.style.top=`${anchor.offsetTop-6}px`;anchor.parentElement.append(tip);requestAnimationFrame(()=>tip.classList.add('show'));tooltipId=setTimeout(()=>{tip.classList.remove('show');setTimeout(()=>tip.remove(),200);},1500);}
function updateAudioIcon(){audioToggle.textContent=audio.muted?'🔇':'🔊';audioToggle.setAttribute('aria-label',audio.muted?'Audio muted — open settings':'Open audio settings');}
function updateHud(){const lives=document.querySelector('#hud-lives');lives.replaceChildren(...Array.from({length:CONFIG.maxLives},(_,index)=>{const heart=document.createElement('span');heart.className=`life-dot ${index>=state.lives?'lost':''}`;return heart;}));document.querySelector('#energy-fill').style.width=`${state.energy}%`;const energyBar=document.querySelector('.energy-bar');energyBar.classList.toggle('warning',state.energy>=34&&state.energy<=66);energyBar.classList.toggle('critical',state.energy<=33);document.querySelector('#hud-energy').textContent=`${state.energy} energy`;document.querySelector('#hud-score').textContent=state.score.toLocaleString();document.querySelector('#hud-secrets').textContent=`${state.secrets}/5`;document.querySelector('#backpack-count').textContent=`${state.inventory.length}/4`;}
function loseEnergyForWrongAnswer(){return false;}
function completeEnergyStep(gameNumber,continuation){if(state.energyEvents.has(gameNumber)){continuation();return;}state.energyEvents.add(gameNumber);state.energy=[67,33,0][(gameNumber-1)%3];updateHud();if(state.energy===0){energyRecoveryContinuation=continuation;showEnergyRecovery();return;}continuation();}
function startTimer(){clearInterval(timerId);timerId=setInterval(()=>{const seconds=Math.floor((Date.now()-state.startedAt)/1000);document.querySelector('#hud-time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;},1000);}
function showStart(){clearInterval(timerId);audio.stopLoop('music');audio.stopLoop('ambience');hud.classList.add('hidden');clearScreen();const composition=artComposition(ASSETS.start,'BLACKOUT start screen');const start=button('start-btn','Start mission'),settings=button('start-settings','Audio settings'),inventory=button('start-inventory','Inventory'),achievements=button('start-achievements','Achievements');start.onclick=()=>{audio.unlock();audio.sfx('click');state.reset();audio.playLoop('music','exploration');showHow();};settings.onclick=event=>{event.stopPropagation();audio.unlock();audio.sfx('click');toggleAudioPanel(true);};inventory.onclick=()=>showTooltip(inventory,'Available during mission');achievements.onclick=()=>showTooltip(achievements,'Unlock during missions');composition.append(start,settings,inventory,achievements);screen.append(composition);}
function showHow(){clearScreen();const firstMissionReady=preloadFirstMissionAssets(),composition=artComposition(ASSETS.how,'How to play BLACKOUT'),back=button('how-back','Back to menu'),go=button('how-go','Begin mission');let missionStarting=false;go.textContent='BEGIN MISSION';back.onclick=()=>{if(missionStarting)return;audio.sfx('click');showStart();};go.onclick=async()=>{if(missionStarting)return;missionStarting=true;go.disabled=true;back.disabled=true;audio.sfx('click');await firstMissionReady;beginMission();};composition.append(back,go);screen.append(composition);}
function beginMission(){if(!state.startedAt)state.startedAt=Date.now();updateHud();startTimer();showHome();}
function showHome(){preloadFirstQuestionPanel();clearScreen();screen.style.backgroundImage=`url('${ASSETS.home}')`;const title=createMissionIntro('HOME BEDROOM','The city just went dark. Answer the emergency phone and find out where to evacuate.','',true);const phone=document.createElement('img');phone.src=ASSETS.phone;phone.className='phone';phone.alt='Ringing emergency phone';phone.tabIndex=0;const callout=document.createElement('div');callout.className='phone-callout';callout.textContent='INCOMING EMERGENCY ALERT';const open=()=>{audio.sfx('select');showPhoneMemory();};phone.onclick=open;phone.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}};screen.append(title,phone,callout);addNightfallCollectible(screen,'medallion');}
function renderPhoneSuccessBriefing(stage){const phoneScreen=stage.querySelector('.phone-memory-screen'),heading=phoneScreen.querySelector('h2'),description=phoneScreen.querySelector('h3'),objective=phoneScreen.querySelector('.phone-memory-status'),briefing=document.createElement('section');briefing.className='phone-success-briefing';heading.textContent='EMERGENCY BROADCAST RECEIVED';description.textContent='CITYWIDE BLACKOUT CONFIRMED';objective.textContent='EVACUATION ORDER: REACH THE RIVERSIDE EVACUATION POINT';briefing.append(heading,description,objective);phoneScreen.append(briefing);}
function showPhoneMemory(){const firstQuestionReady=preloadFirstQuestionPanel();clearScreen();screen.style.backgroundImage=`linear-gradient(#01050bcf,#01050be8),url('${ASSETS.home}')`;const symbols=['▲','●','◆','■'],stage=document.createElement('div');stage.className='phone-memory-stage startup';stage.innerHTML=`<img src="${ASSETS.emergencyConnection}" alt="Emergency connection interface"><section class="phone-memory-screen" aria-live="polite"><p class="phone-memory-round"></p><h2>EMERGENCY CALL INCOMING</h2><h3>RESTORE CONNECTION</h3><div class="phone-memory-sequence"></div><div class="phone-memory-controls"></div><div class="phone-memory-status"></div></section>`;const display=stage.querySelector('.phone-memory-sequence'),controls=stage.querySelector('.phone-memory-controls'),roundLabel=stage.querySelector('.phone-memory-round'),heading=stage.querySelector('h2'),instruction=stage.querySelector('h3'),status=stage.querySelector('.phone-memory-status');let round=0,sequence=[],entered=0,accepting=false;symbols.forEach(symbol=>{const button=document.createElement('button');button.type='button';button.textContent=symbol;button.setAttribute('aria-label',`Enter ${symbol}`);button.onclick=()=>{if(!accepting)return;audio.sfx('select');button.classList.remove('pressed');void button.offsetWidth;button.classList.add('pressed');if(symbol!==sequence[entered]){accepting=false;controls.querySelectorAll('button').forEach(item=>item.disabled=true);stage.classList.add('sequence-error');status.innerHTML='<strong>SEQUENCE ERROR</strong><span>TRY AGAIN</span>';audio.sfx('wrong');transitionId=setTimeout(()=>{stage.classList.remove('sequence-error');showMemoryPhase(false);},950);return;}entered++;if(entered<sequence.length)return;accepting=false;controls.querySelectorAll('button').forEach(item=>item.disabled=true);stage.classList.add('sequence-accepted');status.innerHTML='<strong>SEQUENCE ACCEPTED</strong>';audio.sfx('correct');if(round===3){transitionId=setTimeout(showConnectionSuccess,850);return;}transitionId=setTimeout(()=>{stage.classList.remove('sequence-accepted');round++;sequence=Array.from({length:round+2},()=>symbols[Math.floor(Math.random()*symbols.length)]);showMemoryPhase(true);},850);};controls.append(button);});const showMemoryPhase=()=>{accepting=false;entered=0;controls.classList.remove('visible');controls.querySelectorAll('button').forEach(button=>button.disabled=true);status.replaceChildren();roundLabel.textContent=`ROUND ${round} / 3`;heading.textContent='MEMORIZE THE SEQUENCE';instruction.textContent='';display.textContent=sequence.join('     ');display.classList.add('visible');transitionId=setTimeout(()=>{display.classList.remove('visible');display.textContent='';heading.textContent='REPEAT THE SEQUENCE';controls.classList.add('visible');controls.querySelectorAll('button').forEach(button=>button.disabled=false);accepting=true;},2000);};const showConnectionSuccess=()=>{stage.classList.remove('sequence-accepted');controls.classList.remove('visible');display.replaceChildren();roundLabel.textContent='';stage.classList.add('connection-established');renderPhoneSuccessBriefing(stage);audio.sfx('complete');transitionId=setTimeout(async()=>{await firstQuestionReady;state.game=1;state.questionIndex=0;state.gameProgress=0;showQuestion();},READABLE_MESSAGE_DURATION);};screen.append(stage);transitionId=setTimeout(()=>{stage.classList.remove('startup');round=1;sequence=Array.from({length:3},()=>symbols[Math.floor(Math.random()*symbols.length)]);showMemoryPhase(true);},1050);}
function currentGrammarData(){return state.game===5?ERROR_DETECTOR_DATA:state.game===4?SIGNAL_SCANNER_DATA:state.game===3?SUPPLY_SEARCH_DATA:state.game===2?STREET_SIGNALS_DATA:GRAMMAR_DATA;}
function showQuestion(){if(state.game===4){showTunnelDrive();return;}if(state.game===3){showSupplySearchScene();return;}if(state.game===2){showStreetGridQuestion();return;}locked=false;state.lives=3;updateHud();clearScreen();const questions=currentGrammarData(),question=questions[state.questionIndex];const stage=document.createElement('div');stage.className='question-stage';const panel=document.createElement('div');panel.className='question-panel';const copy=document.createElement('div');copy.className='question-copy';copy.innerHTML='<p class="eyebrow">GAME 1 — EMERGENCY PHONE</p><p class="instruction">Choose the correct answer.</p><p class="sentence"></p>';copy.querySelector('.sentence').textContent=question.sentence||'';const answers=document.createElement('div');answers.className='answers';question.options.forEach(option=>{const answer=document.createElement('button');const answerCopy=document.createElement('span');answer.className='answer';answerCopy.className='answer-copy';answerCopy.textContent=option;answer.append(answerCopy);answer.setAttribute('aria-label',option);answer.onclick=()=>answerQuestion(answer,option);answers.append(answer);});panel.append(copy,answers);stage.append(panel);screen.append(stage);if(state.energy===0)showEnergyRecovery();}
const renderHomeWithoutHud=showHome;showHome=function(){hud.classList.add('hidden');renderHomeWithoutHud();};
const renderPhoneMemoryWithHud=showPhoneMemory;showPhoneMemory=function(){hud.classList.remove('hidden');renderPhoneMemoryWithHud();const stage=screen.querySelector('.phone-memory-stage');if(!stage)return;const observer=new MutationObserver(()=>{if(!stage.classList.contains('connection-established'))return;observer.disconnect();clearTimeout(transitionId);transitionId=0;if(DEV_REQUEST==='phone-success')return;transitionId=setTimeout(async()=>{await preloadFirstQuestionPanel();state.game=1;state.questionIndex=0;state.gameProgress=0;showQuestion();},READABLE_MESSAGE_DURATION);});observer.observe(stage,{attributes:true,attributeFilter:['class']});};
const renderQuestionWithHud=showQuestion;showQuestion=function(){hud.classList.remove('hidden');renderQuestionWithHud();};
function createStreetGrid(poweredCount=state.gameProgress){const grid=document.createElement('div');grid.className='street-power-grid';grid.innerHTML=`<img src="${ASSETS.streetPowerGrid}" alt="Street power network"><div class="street-grid-nodes" aria-hidden="true"></div>`;const nodes=grid.querySelector('.street-grid-nodes');for(let index=0;index<4;index++){const node=document.createElement('i');node.className=`street-grid-node node-${index+1}${index<poweredCount?' powered':''}`;nodes.append(node);}return grid;}
function showStreetGridQuestion(){locked=false;state.lives=3;updateHud();clearScreen();const question=STREET_SIGNALS_DATA[state.questionIndex],stage=document.createElement('div');stage.className='street-grid-stage';stage.style.backgroundImage=`linear-gradient(#030912b8,#070404c4),url('${ASSETS.blackoutStreet}')`;stage.innerHTML=`<header class="street-grid-question"><p>GAME 2 — STREET SIGNALS</p><strong>RESTORE THE STREET GRID</strong><span></span></header><output class="street-grid-progress">GRID POWER ${state.gameProgress*25}%</output>`;stage.querySelector('.street-grid-question span').textContent=question.sentence;const grid=createStreetGrid();const signals=document.createElement('div');signals.className='street-grid-signals';question.options.forEach((option,index)=>{const signal=document.createElement('button');signal.type='button';signal.className=`street-signal signal-${index+1}`;signal.textContent=option;signal.setAttribute('aria-label',option);signal.onclick=()=>answerStreetSignal(stage,signal,option);signals.append(signal);});stage.append(grid,signals);addNightfallCollectible(stage,'usb');screen.append(stage);if(state.energy===0)showEnergyRecovery();}
function answerStreetSignal(stage,signal,choice){if(locked)return;const question=STREET_SIGNALS_DATA[state.questionIndex];if(choice===question.answer){locked=true;stage.querySelectorAll('.street-signal').forEach(item=>item.disabled=true);signal.classList.add('correct');state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;state.gameProgress++;const node=stage.querySelector(`.node-${state.gameProgress}`),stageRect=stage.getBoundingClientRect(),signalRect=signal.getBoundingClientRect(),nodeRect=node.getBoundingClientRect(),pulse=document.createElement('i');pulse.className='street-travel-pulse';pulse.style.left=`${signalRect.left-stageRect.left+signalRect.width/2}px`;pulse.style.top=`${signalRect.top-stageRect.top+signalRect.height/2}px`;pulse.style.setProperty('--travel-x',`${nodeRect.left-signalRect.left+(nodeRect.width-signalRect.width)/2}px`);pulse.style.setProperty('--travel-y',`${nodeRect.top-signalRect.top+(nodeRect.height-signalRect.height)/2}px`);stage.append(pulse);setTimeout(()=>{node.classList.add('powered','powering');stage.querySelector('.street-grid-progress').textContent=`GRID POWER ${state.gameProgress*25}%`;},720);audio.sfx('correct');updateHud();showFeedback(`CORRECT +${CONFIG.multipleChoiceScore}`,'good',1450);transitionId=setTimeout(nextQuestion,1500);return;}signal.classList.add('wrong');setTimeout(()=>signal.classList.remove('wrong'),500);audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;stage.querySelectorAll('.street-signal').forEach(item=>item.disabled=true);transitionId=setTimeout(launchEmergencyRescue,750);}}
function answerQuestion(buttonElement,choice){if(locked)return;const question=currentGrammarData()[state.questionIndex];if(choice===question.answer){locked=true;buttonElement.classList.add('correct');document.querySelectorAll('.answer').forEach(answer=>answer.disabled=true);state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;if(state.game===2||state.game===4)state.gameProgress++;audio.sfx('correct');updateHud();showFeedback(`CORRECT +${CONFIG.multipleChoiceScore}`,'good',1450);transitionId=setTimeout(nextQuestion,1500);return;}buttonElement.classList.add('wrong');setTimeout(()=>buttonElement.classList.remove('wrong'),500);audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;document.querySelectorAll('.answer').forEach(answer=>answer.disabled=true);transitionId=setTimeout(launchEmergencyRescue,750);}}
function nextQuestion(){state.questionIndex++;if(state.game===2?state.questionIndex<4:state.questionIndex<currentGrammarData().length)showQuestion();else if(state.game===1)showGameOneComplete();else if(state.game===2)showGameTwoComplete();else showServiceTunnelsComplete();}
function showGameOneComplete(){audio.sfx('complete');clearScreen();screen.style.backgroundImage=`url('${ASSETS.home}')`;const gameTwoReady=preloadImages([ASSETS.blackoutStreet,ASSETS.streetPowerGrid,NIGHTFALL_COLLECTIBLES.usb.asset]);const success=document.createElement('div');success.className='mission-success';success.innerHTML='<h2>EVACUATION ROUTE RECEIVED ✓</h2><p>GAME 1 COMPLETE</p>';screen.append(success);transitionId=setTimeout(()=>completeEnergyStep(1,async()=>{await gameTwoReady;showBlackoutStreet();}),READABLE_MESSAGE_DURATION);}
function showBlackoutStreet(){clearScreen();screen.classList.add('scene-arrival');screen.style.backgroundImage=`url('${ASSETS.blackoutStreet}')`;screen.append(createMissionIntro('BLACKOUT STREET','Emergency signals mark a route toward the evacuation point.','RESTORE THE STREET SIGNALS'));transitionId=setTimeout(()=>{state.game=2;state.questionIndex=0;state.gameProgress=0;showQuestion();},BETWEEN_GAME_TRANSITION_MS);}
function showGameTwoComplete(){audio.sfx('complete');clearScreen();const supplyReady=preloadImages([ASSETS.supermarketExteriorBlackout,ASSETS.supermarketExterior,ASSETS.supermarketInterior,'assets/ui/typing_panel.png',...SUPPLY_SEARCH_DATA.map(item=>item.asset)]),stage=document.createElement('div');stage.className='street-grid-stage street-grid-complete';stage.style.backgroundImage=`linear-gradient(#030912b8,#070404c4),url('${ASSETS.blackoutStreet}')`;stage.innerHTML='<output class="street-grid-progress">GRID POWER 100%</output>';stage.append(createStreetGrid(4));screen.append(stage);transitionId=setTimeout(()=>{stage.classList.add('network-powered');const success=document.createElement('div');success.className='mission-success street-grid-success';success.innerHTML='<h2>STREET NETWORK RESTORED ✓</h2><p>GAME 2 COMPLETE</p>';stage.append(success);transitionId=setTimeout(()=>completeEnergyStep(2,async()=>{await supplyReady;showSupplySearchIntro();}),READABLE_MESSAGE_DURATION);},700);}
function showSupplySearchIntro(){clearScreen();screen.classList.add('scene-arrival');screen.style.backgroundImage=`url('${ASSETS.supermarketExteriorBlackout}')`;screen.append(createMissionIntro('SUPPLY SEARCH','Collect essential supplies before continuing toward evacuation.','RECOVER SUPPLIES'));transitionId=setTimeout(()=>{state.game=3;state.questionIndex=0;state.gameProgress=0;showQuestion();},BETWEEN_GAME_TRANSITION_MS);}
function normalizeTypedAnswer(value){return value.trim().toLowerCase().replace(/[‘’]/g,"'").replace(/\s+/g,' ');}
function showSupplySearchScene(){locked=false;state.lives=3;updateHud();clearScreen();const question=SUPPLY_SEARCH_DATA[state.questionIndex],stage=document.createElement('div');stage.className='supply-search-stage flashlight-active';stage.style.backgroundImage=`url('${ASSETS.supermarketInterior}')`;stage.innerHTML='<div class="supply-darkness" aria-hidden="true"></div><div class="supply-beam" aria-hidden="true"></div><header class="supply-search-instruction"><strong>SUPPLY SEARCH</strong><span>Use your flashlight to find 4 supplies:<br>Water • First Aid Kit • Chocolate • Batteries</span><b></b></header>';screen.append(stage);activateSupplyFlashlight(stage,question);if(state.energy===0)showEnergyRecovery();}
function activateSupplyFlashlight(stage,question){const instruction=stage.querySelector('.supply-search-instruction'),searchNames=['WATER','FIRST AID KIT','CHOCOLATE','BATTERIES'],target=document.createElement('button');instruction.querySelector('b').textContent=`CURRENT TARGET: ${searchNames[state.questionIndex]}`;target.type='button';target.className=`supply-search-target supply-target-${state.questionIndex+1}`;target.setAttribute('aria-label',`Find ${question.reward}`);target.innerHTML=`<img src="${question.asset}" alt="${question.reward}">`;target.onclick=()=>{if(locked)return;locked=true;target.classList.add('found');audio.sfx('select');transitionId=setTimeout(()=>showTypingQuestion(stage),420);};stage.append(target);let targetX=50,targetY=42,currentX=50,currentY=42;stage.onpointermove=event=>{const bounds=stage.getBoundingClientRect();targetX=Math.max(2,Math.min(98,(event.clientX-bounds.left)/bounds.width*100));targetY=Math.max(25,Math.min(96,(event.clientY-bounds.top)/bounds.height*100));};const followBeam=()=>{if(!document.body.contains(stage))return;currentX+=(targetX-currentX)*.14;currentY+=(targetY-currentY)*.14;stage.style.setProperty('--beam-x',`${currentX}%`);stage.style.setProperty('--beam-y',`${currentY}%`);const bounds=stage.getBoundingClientRect(),targetBounds=target.getBoundingClientRect(),targetCenterX=targetBounds.left+targetBounds.width/2,targetCenterY=targetBounds.top+targetBounds.height/2,cursorX=bounds.left+currentX/100*bounds.width,cursorY=bounds.top+currentY/100*bounds.height;target.classList.toggle('illuminated',Math.hypot(targetCenterX-cursorX,targetCenterY-cursorY)<bounds.width*.18);requestAnimationFrame(followBeam);};requestAnimationFrame(followBeam);}
function showTypingQuestion(stage=screen.querySelector('.supply-search-stage')){locked=false;const question=SUPPLY_SEARCH_DATA[state.questionIndex];stage.classList.add('search-paused');const overlay=document.createElement('div');overlay.className='supply-grammar-overlay';const panel=document.createElement('div');panel.className='typing-panel';const copy=document.createElement('div');copy.className='typing-panel-copy';copy.innerHTML='<p class="eyebrow">GAME 3 — SUPPLY SEARCH</p><p class="instruction">Type the correct verb form.</p><p class="sentence"></p>';copy.querySelector('.sentence').textContent=question.sentence;const controls=document.createElement('form');controls.className='typing-panel-controls';controls.innerHTML='<input class="typing-input" type="text" placeholder="Type your answer here..." autocomplete="off" aria-label="Type the correct verb form"><button type="submit" aria-label="Submit answer"></button>';controls.onsubmit=event=>{event.preventDefault();submitTypedAnswer(controls.querySelector('.typing-input'));};panel.append(copy,controls);overlay.append(panel);stage.append(overlay);controls.querySelector('.typing-input').focus();}
function submitTypedAnswer(input){if(locked)return;const question=SUPPLY_SEARCH_DATA[state.questionIndex];if(normalizeTypedAnswer(input.value)===normalizeTypedAnswer(question.answer)){locked=true;input.disabled=true;input.form.querySelector('button').disabled=true;state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;state.gameProgress++;audio.sfx('correct');updateHud();showFeedback(`CORRECT +${CONFIG.multipleChoiceScore}`,'good',1450);transitionId=setTimeout(()=>awardSupplyItem(question),650);return;}input.classList.remove('wrong');void input.offsetWidth;input.classList.add('wrong');audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;input.disabled=true;input.form.querySelector('button').disabled=true;transitionId=setTimeout(launchEmergencyRescue,750);return;}input.focus();input.select();}
function awardSupplyItem(question){if(state.inventory.includes(question.reward)){advanceSupplySearch();return;}audio.sfx('itemPickup');const reward=document.createElement('div');reward.className='item-found';reward.innerHTML=`<div class="reward-card"><p>SUPPLY ACQUIRED</p><img src="${question.asset}" alt="${question.reward}"><strong>${question.reward.toUpperCase()}</strong></div>`;screen.append(reward);const item=reward.querySelector('img');transitionId=setTimeout(()=>{state.inventory.push(question.reward);const itemBox=item.getBoundingClientRect(),backpackBox=document.querySelector('.backpack-icon').getBoundingClientRect();item.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${backpackBox.left+backpackBox.width/2-itemBox.left-itemBox.width/2}px,${backpackBox.top+backpackBox.height/2-itemBox.top-itemBox.height/2}px) scale(.12)`,opacity:0}],{duration:900,easing:'ease-in',fill:'forwards'}).finished.then(()=>{updateHud();document.querySelector('#backpack').classList.add('collect-pulse');setTimeout(()=>document.querySelector('#backpack').classList.remove('collect-pulse'),650);advanceSupplySearch();});},READABLE_MESSAGE_DURATION);}
