function showGameThreeComplete(){audio.sfx('complete');clearScreen();screen.style.backgroundImage=`url('${ASSETS.supermarketExterior}')`;const routesReady=preloadImages([ASSETS.routeSelection,ASSETS.serviceTunnels,ASSETS.tunnelRoutes,ASSETS.interactive.car,NIGHTFALL_COLLECTIBLES.processor.asset]),success=document.createElement('div');success.className='mission-success';success.innerHTML='<h2>SUPPLIES SECURED ✓</h2><p>GAME 3 COMPLETE</p>';screen.append(success);transitionId=setTimeout(()=>completeEnergyStep(3,async()=>{await routesReady;showRouteSelection();}),READABLE_MESSAGE_DURATION);}
function showRouteSelection(){clearTimeout(routeMessageId);clearScreen();const composition=artComposition(ASSETS.routeSelection,'Sequential sectors: Service Tunnels, City Streets, Main Bridge');composition.classList.add('route-selection');const allComplete=state.serviceTunnelsCompleted&&state.cityStreetsCompleted&&state.mainBridgeCompleted;const baseInstruction=allComplete?'<strong>ALL SECTORS COMPLETE ✓</strong><span>CITY NETWORK MAPPED</span>':state.cityStreetsCompleted?'<strong>FINAL SECTOR UNLOCKED</strong><span>Cross the Main Bridge.</span>':state.serviceTunnelsCompleted?'<strong>SECTOR 2 UNLOCKED</strong><span>Proceed through City Streets.</span>':'<strong>SECTOR 1 AVAILABLE</strong><span>Proceed through Service Tunnels.</span>';const instruction=document.createElement('div');instruction.className='route-instruction';instruction.innerHTML=baseInstruction;const routes=[['serviceTunnels','serviceTunnelsCompleted','Service Tunnels'],['cityStreets','cityStreetsCompleted','City Streets'],['mainBridge','mainBridgeCompleted','Main Bridge']];routes.forEach(([route,key,label],index)=>{const completed=state[key],available=!allComplete&&((route==='serviceTunnels'&&!state.serviceTunnelsCompleted)||(route==='cityStreets'&&state.serviceTunnelsCompleted&&!state.cityStreetsCompleted)||(route==='mainBridge'&&state.cityStreetsCompleted&&!state.mainBridgeCompleted)),routeState=completed?'completed':available?'available':'locked';const choice=button(`route-choice route-${index+1} ${routeState}`,`${label}: ${routeState}`);choice.disabled=completed;choice.innerHTML=completed?'✓ COMPLETED':routeState==='locked'?'🔒 LOCKED':'';choice.onclick=()=>{if(available)selectRoute(route,label);else if(!completed)showRouteLocked(route,instruction,baseInstruction);};const shade=document.createElement('div');shade.className=`route-card-shade route-card-${index+1} ${routeState}`;composition.append(choice,shade);});composition.append(instruction);screen.append(composition);}
const renderRouteSelectionWithRaisedHud=showRouteSelection;showRouteSelection=function(){renderRouteSelectionWithRaisedHud();hud.classList.add('route-screen-hud');};
function showRouteLocked(route,instruction,baseInstruction){const requirement=route==='cityStreets'||!state.serviceTunnelsCompleted?'Complete Service Tunnels first.':'Complete City Streets first.';instruction.innerHTML=`<strong>ROUTE LOCKED</strong><span>${requirement}</span>`;clearTimeout(routeMessageId);routeMessageId=setTimeout(()=>instruction.innerHTML=baseInstruction,READABLE_MESSAGE_DURATION);}
async function selectRoute(route,label){screen.querySelectorAll('.route-choice').forEach(choice=>choice.disabled=true);state.selectedRoute=route;audio.sfx('select');const routeAssets=route==='serviceTunnels'?[ASSETS.serviceTunnels,ASSETS.tunnelRoutes,ASSETS.interactive.car,NIGHTFALL_COLLECTIBLES.processor.asset]:route==='cityStreets'?[ASSETS.cityStreets]:route==='mainBridge'?[ASSETS.mainBridge,NIGHTFALL_COLLECTIBLES.fieldNotes.asset]:[];await preloadImages(routeAssets);if(route==='serviceTunnels'){showServiceTunnelsIntro();return;}if(route==='cityStreets'){showCityStreetsIntro();return;}if(route==='mainBridge'){showMainBridgeIntro();return;}const instruction=document.querySelector('.route-instruction');if(instruction)instruction.innerHTML=`<strong>${label.toUpperCase()} SELECTED</strong><span>Route gameplay will continue here.</span>`;}
