function checkpointAnswerMatches(value,module,index){const accepted=module.acceptedAnswers?.[index]||[module.answers[index]];return accepted.some(answer=>normalizeTypedAnswer(value)===normalizeTypedAnswer(answer));}
function submitCheckpointAnswer(form,module){if(locked)return;const inputs=[...form.querySelectorAll('input')],correct=inputs.every((input,index)=>checkpointAnswerMatches(input.value,module,index));if(correct){completeCheckpointModule(module);return;}inputs.forEach((input,index)=>input.classList.toggle('wrong',!checkpointAnswerMatches(input.value,module,index)));checkpointWrong(inputs,form.querySelector('button'));}
function answerCheckpointChoice(buttonElement,choice,module){if(locked)return;if(choice===module.answer){buttonElement.classList.add('correct');completeCheckpointModule(module);return;}buttonElement.classList.remove('wrong');void buttonElement.offsetWidth;buttonElement.classList.add('wrong');checkpointWrong([],null);}
function checkpointWrong(inputs,submit){audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;inputs.forEach(input=>input.disabled=true);if(submit)submit.disabled=true;document.querySelectorAll('.checkpoint-answers button').forEach(button=>button.disabled=true);transitionId=setTimeout(launchEmergencyRescue,750);return;}const firstWrong=inputs.find(input=>input.classList.contains('wrong'));firstWrong?.focus();firstWrong?.select();}
function completeCheckpointModule(module){if(locked)return;locked=true;state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;state.gameProgress++;audio.sfx('correct');updateHud();document.querySelector(`.module-${state.questionIndex+1}`)?.classList.add('restored');const status=document.querySelector(`.status-${state.questionIndex+1}`);if(status){status.classList.add('online');status.textContent=module.status;}document.querySelectorAll('.checkpoint-challenge input,.checkpoint-challenge button').forEach(control=>control.disabled=true);showFeedback(module.status,'good',1400);transitionId=setTimeout(()=>{state.questionIndex++;if(state.questionIndex<CHECKPOINT_DATA.length)showCheckpointStage();else showCheckpointComplete();},1450);}
function showCheckpointComplete(){audio.sfx('complete');clearScreen();screen.classList.add('checkpoint-complete');screen.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;const transmissionReady=preloadImages([ASSETS.transmissionRooftop,ASSETS.interactive.transmissionHelicopter]),board=document.createElement('div');board.className='checkpoint-board all-restored';board.innerHTML=`<img src="${ASSETS.interactive.checkpointPanel}" alt="Checkpoint control panel restored"><div class="checkpoint-statuses"></div>`;const statuses=board.querySelector('.checkpoint-statuses');CHECKPOINT_DATA.forEach((module,index)=>{const status=document.createElement('span');status.className=`checkpoint-status status-${index+1} online`;status.textContent=module.status;statuses.append(status);});const success=document.createElement('div');success.className='mission-success checkpoint-success';success.innerHTML='<h2>CHECKPOINT RESTORED</h2><p>SYSTEMS RESTORED: 4/4</p>';screen.append(board,success);transitionId=setTimeout(()=>completeEnergyStep(10,async()=>{await transmissionReady;showGameElevenLocked();}),CITY_TRANSITION_MS);}
function showGameElevenLocked(){clearScreen();screen.classList.add('scene-arrival');screen.style.backgroundImage=`url('${ASSETS.transmissionRooftop}')`;screen.append(createMissionIntro('EMERGENCY TRANSMISSION','All ground evacuation routes are unsafe. A rescue helicopter is searching for your signal.','TRANSMIT FOUR PACKETS'));transitionId=setTimeout(()=>{state.game=11;state.questionIndex=0;state.gameProgress=0;showEmergencyTransmissionPacket();},CITY_TRANSITION_MS);}
function startHelicopterAmbience(stage){if(helicopterAmbience)return;const track=new Audio(ASSETS.helicopterAmbience);track.loop=true;track.preload='metadata';track.volume=audio.muted?0:.03;helicopterAmbience=track;const play=()=>{audio.unlock();if(helicopterAmbience===track)track.play().catch(()=>{});};if(audio.enabled)play();else stage.addEventListener('pointerdown',play,{once:true});}
function stopHelicopterAmbience(){if(!helicopterAmbience)return;helicopterAmbience.pause();helicopterAmbience.currentTime=0;helicopterAmbience=null;}
function showEmergencyTransmissionPacket(){locked=false;state.lives=3;updateHud();clearScreen();const packet=EMERGENCY_TRANSMISSION_DATA[state.questionIndex],stage=document.createElement('div');stage.className=`transmission-game packet-${state.questionIndex+1}`;stage.style.backgroundImage=`url('${ASSETS.transmissionRooftop}')`;stage.style.setProperty('--helicopter-speed',`${packet.speed}s`);stage.innerHTML='<header class="transmission-header"><p>GAME 11 — EMERGENCY TRANSMISSION</p><strong>Complete the message. Then wait until the helicopter enters the SIGNAL ZONE and click on the helicopter.</strong><span></span></header><div class="helicopter-flight"><div class="signal-zone" aria-hidden="true"></div><button class="moving-helicopter" type="button" aria-label="Rescue helicopter"><img alt="Rescue helicopter"></button></div><section class="transmission-terminal"><div class="transmission-clues"></div><form class="transmission-form"><p></p><button type="submit">CHECK MESSAGE</button></form></section>';stage.querySelector('.transmission-header span').textContent=`TRANSMISSION: ${state.gameProgress*25}%`;stage.querySelector('.moving-helicopter img').src=ASSETS.interactive.transmissionHelicopter;const clues=stage.querySelector('.transmission-clues');(packet.clues||[]).forEach(text=>{const clue=document.createElement('span');clue.textContent=text;clues.append(clue);});const form=stage.querySelector('.transmission-form'),sentence=form.querySelector('p');packet.parts.forEach((part,index)=>{sentence.append(document.createTextNode(part));if(index<packet.answers.length){const input=document.createElement('input');input.type='text';input.autocomplete='off';input.size=Math.max(10,packet.answers[index][0].length+1);input.setAttribute('aria-label',`Transmission verb form ${index+1}`);sentence.append(input);}});form.onsubmit=event=>{event.preventDefault();submitTransmissionGrammar(form,packet,stage);};stage.querySelector('.signal-zone').classList.add(`zone-${packet.zone}`);stage.querySelector('.moving-helicopter').onclick=event=>{event.stopPropagation();attemptPacketTransmission(stage);};stage.onclick=event=>{if(stage.dataset.transmissionReady==='true'&&!event.target.closest('.moving-helicopter'))showFeedback('SIGNAL MISSED — TRY AGAIN','info',750);};screen.append(stage);startHelicopterAmbience(stage);form.querySelector('input').focus();if(state.energy===0)showEnergyRecovery();}
function transmissionAnswerMatches(value,answers){return answers.some(answer=>normalizeTypedAnswer(value)===normalizeTypedAnswer(answer));}
function submitTransmissionGrammar(form,packet,stage){if(locked)return;const inputs=[...form.querySelectorAll('input')],correct=inputs.every((input,index)=>transmissionAnswerMatches(input.value,packet.answers[index]));if(correct){locked=true;inputs.forEach(input=>{input.disabled=true;input.classList.add('correct');});form.querySelector('button').disabled=true;state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;audio.sfx('correct');updateHud();showFeedback('PACKET READY','good',900);transitionId=setTimeout(()=>preparePacketTransmission(stage),550);return;}inputs.forEach((input,index)=>input.classList.toggle('wrong',!transmissionAnswerMatches(input.value,packet.answers[index])));audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'TRANSMISSION ERROR — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;inputs.forEach(input=>input.disabled=true);form.querySelector('button').disabled=true;stopHelicopterAmbience();transitionId=setTimeout(launchEmergencyRescue,750);return;}const firstWrong=inputs.find(input=>input.classList.contains('wrong'));firstWrong?.focus();firstWrong?.select();}
function preparePacketTransmission(stage){if(!document.body.contains(stage))return;locked=false;stage.dataset.transmissionReady='true';stage.classList.add('transmission-active');const terminal=stage.querySelector('.transmission-terminal');terminal.innerHTML='<strong>PACKET READY</strong><p>WAIT UNTIL THE HELICOPTER ENTERS THE SIGNAL ZONE<br>THEN CLICK THE HELICOPTER</p><output>TRANSMISSION WINDOW: 15</output>';startTransmissionCountdown(stage,15);}
function helicopterInsideSignalZone(stage){const helicopter=stage.querySelector('.moving-helicopter')?.getBoundingClientRect(),zone=stage.querySelector('.signal-zone')?.getBoundingClientRect();if(!helicopter||!zone)return false;const center=helicopter.left+helicopter.width/2;return center>=zone.left&&center<=zone.right;}
function startTransmissionCountdown(stage,seconds){clearInterval(transmissionCountdownId);let remaining=seconds;const output=stage.querySelector('.transmission-terminal output');if(output)output.textContent=`TRANSMISSION WINDOW: ${remaining}`;transmissionCountdownId=setInterval(()=>{remaining--;if(output)output.textContent=`TRANSMISSION WINDOW: ${remaining}`;if(remaining<=0){clearInterval(transmissionCountdownId);transmissionCountdownId=0;connectionLost(stage);}},1000);}
function attemptPacketTransmission(stage){if(locked||stage.dataset.transmissionReady!=='true')return;if(!helicopterInsideSignalZone(stage)){showFeedback('SIGNAL MISSED — TRY AGAIN','info',750);return;}locked=true;stage.dataset.transmissionReady='false';clearInterval(transmissionCountdownId);transmissionCountdownId=0;state.gameProgress++;updateHud();stage.querySelector('.transmission-header span').textContent=`TRANSMISSION: ${state.gameProgress*25}%`;stage.classList.add('packet-sent','signal-success');setTimeout(()=>stage.classList.remove('signal-success'),800);audio.sfx('correct');showFeedback(`PACKET ${state.gameProgress} TRANSMITTED ✓`,'good',1200);transitionId=setTimeout(()=>{state.questionIndex++;if(state.questionIndex<EMERGENCY_TRANSMISSION_DATA.length)showEmergencyTransmissionPacket();else showEmergencyTransmissionComplete();},1300);}
function connectionLost(stage){if(!document.body.contains(stage))return;locked=true;stage.dataset.transmissionReady='false';stage.classList.add('reconnecting');const terminal=stage.querySelector('.transmission-terminal');terminal.innerHTML='<strong>CONNECTION LOST</strong><p>RECONNECTING...</p>';transitionId=setTimeout(()=>{if(!document.body.contains(stage))return;locked=false;stage.dataset.transmissionReady='true';stage.classList.remove('reconnecting');terminal.innerHTML='<strong>PACKET READY</strong><p>WAIT UNTIL THE HELICOPTER ENTERS THE SIGNAL ZONE<br>THEN CLICK THE HELICOPTER</p><output>TRANSMISSION WINDOW: 15</output>';startTransmissionCountdown(stage,15);},2500);}
function showEmergencyTransmissionComplete(){clearInterval(transmissionCountdownId);transmissionCountdownId=0;stopHelicopterAmbience();audio.sfx('complete');clearScreen();screen.classList.add('transmission-complete');screen.style.backgroundImage=`url('${ASSETS.transmissionRooftop}')`;const evacuationReady=preloadImages([ASSETS.evacuationPoint,ASSETS.interactive.passengerTerminal,ASSETS.interactive.landingLights,ASSETS.interactive.securityGateBase,ASSETS.interactive.securityGateBarrier,ASSETS.interactive.conveyorBox,...Object.values(NIGHTFALL_COLLECTIBLES).map(item=>item.asset)]),helicopter=document.createElement('img');helicopter.className='final-helicopter-pass';helicopter.src=ASSETS.interactive.transmissionHelicopter;helicopter.alt='Rescue helicopter inbound';const success=document.createElement('div');success.className='mission-success transmission-success';success.innerHTML='<h2>SIGNAL LOCKED</h2><p>COORDINATES TRANSMITTED</p><strong>RESCUE HELICOPTER INBOUND</strong>';screen.append(helicopter,success);transitionId=setTimeout(()=>completeEnergyStep(11,async()=>{await evacuationReady;showGameTwelveLocked();}),READABLE_MESSAGE_DURATION);}
function showGameTwelveLocked(){stopHelicopterAmbience();clearScreen();screen.classList.add('scene-arrival');screen.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;screen.append(createMissionIntro('EVACUATION POINT','You reached the riverside evacuation point. Prepare every system for helicopter extraction.','FINAL EVACUATION CLEARANCE'));transitionId=setTimeout(()=>{state.game=12;state.questionIndex=0;state.gameProgress=0;state.game12Completed=[];state.game12ActiveStation=null;state.game12ObstaclesCleared=false;showEvacuationScene();},CITY_TRANSITION_MS);}
function evacuationStationComplete(id){return state.game12Completed.includes(id);}
function evacuationPrerequisitesComplete(){return ['passengers','lights','gate'].every(evacuationStationComplete);}
function showEvacuationScene(recent=''){locked=false;updateHud();clearScreen();const stage=document.createElement('div');stage.className='evacuation-game';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;stage.innerHTML='<header class="evacuation-header"><p>GAME 12 — FINAL SURVIVAL CHALLENGE</p><strong>FINAL EVACUATION CLEARANCE</strong><span>Complete all four tasks to authorize evacuation.</span><output></output></header><div class="evacuation-stations"></div>';stage.querySelector('output').textContent=`FINAL CLEARANCE: ${state.game12Completed.length*25}%`;const stations=stage.querySelector('.evacuation-stations'),definitions=[['passengers','REGISTER PASSENGERS','passengerTerminal'],['lights','LANDING LIGHTS','landingLights'],['gate','SECURITY GATE','securityGateBase'],['landing','LANDING ZONE','conveyorBox']];definitions.forEach(([id,label,asset])=>{const completed=evacuationStationComplete(id),available=id!=='landing'||evacuationPrerequisitesComplete();const station=document.createElement('button');station.type='button';station.className=`evacuation-station station-${id} ${completed?'completed':''} ${recent===id?'just-completed':''} ${available?'available':'locked'}`;station.disabled=completed||!available;station.setAttribute('aria-label',completed?`${label} complete`:available?label:`${label} locked`);if(id==='gate')station.innerHTML=`<span class="gate-layers"><img class="gate-base" src="${ASSETS.interactive.securityGateBase}" alt=""><img class="gate-barrier" src="${ASSETS.interactive.securityGateBarrier}" alt=""></span>`;else station.innerHTML=`<img src="${ASSETS.interactive[asset]}" alt="">`;if(id==='lights')station.insertAdjacentHTML('beforeend','<span class="light-sequence" aria-hidden="true"><i></i><i></i><i></i></span>');station.insertAdjacentHTML('beforeend',`<span class="station-label">${label}</span><b>${completed?'✓':''}</b><em>${completed?(id==='passengers'?'REGISTERED ✓':'COMPLETE ✓'):id==='landing'&&!available?'COMPLETE OTHER SYSTEMS FIRST':'SELECT'}</em>`);station.onclick=()=>openEvacuationStation(id);stations.append(station);});screen.append(stage);}
function openEvacuationStation(id){if(evacuationStationComplete(id))return;if(id==='landing'){if(!evacuationPrerequisitesComplete())return;if(state.game12ObstaclesCleared)showEvacuationTask('landing');else showLandingZoneClearance();return;}showEvacuationTask(id);}
function evacuationTaskShell(instruction){locked=false;state.lives=3;updateHud();clearScreen();const stage=document.createElement('div');stage.className='evacuation-task';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;const panel=document.createElement('section');panel.className='evacuation-task-panel';panel.innerHTML=`<h2>GAME 12 — FINAL SURVIVAL CHALLENGE</h2><strong>${instruction}</strong><div class="evacuation-task-content"></div>`;stage.append(panel);screen.append(stage);return {stage,panel,content:panel.querySelector('.evacuation-task-content')};}
function showEvacuationTask(id){state.game12ActiveStation=id;const task=FINAL_SURVIVAL_DATA[id];if(id==='passengers'){const {content}=evacuationTaskShell('Choose the correct answer.');content.innerHTML='<p class="evacuation-sentence"></p><div class="evacuation-answers"></div>';content.querySelector('p').textContent=task.sentence;task.options.forEach((option,index)=>{const choice=document.createElement('button');choice.type='button';choice.textContent=`${String.fromCharCode(65+index)}) ${option}`;choice.onclick=()=>{if(locked)return;if(option===task.answer){choice.classList.add('correct');completeEvacuationStation(id,'PASSENGER REGISTRATION COMPLETE ✓');}else evacuationWrong([choice]);};content.querySelector('.evacuation-answers').append(choice);});return;}if(id==='lights'){const {content}=evacuationTaskShell('Type the correct verb form.');content.innerHTML='<form class="evacuation-form"><p class="evacuation-sentence"></p><button type="submit">ACTIVATE LIGHTS</button></form>';const form=content.querySelector('form'),sentence=form.querySelector('p'),input=document.createElement('input');input.type='text';input.autocomplete='off';input.placeholder='Type your answer';input.setAttribute('aria-label','Correct form of circle');sentence.append(document.createTextNode('The helicopter '),input,document.createTextNode(' (circle) above the evacuation zone for several minutes.'));form.onsubmit=event=>{event.preventDefault();if(locked)return;if(normalizeTypedAnswer(input.value)===task.answer)completeEvacuationStation(id,'LANDING LIGHTS ACTIVATED ✓');else evacuationWrong([input]);};input.focus();return;}if(id==='gate'){const {content}=evacuationTaskShell('Find the mistake and correct it.');content.innerHTML='<p class="evacuation-gate-sentence"></p><div class="evacuation-correction"></div>';const sentence=content.querySelector('.evacuation-gate-sentence');task.segments.forEach(segment=>{const choice=document.createElement('button');choice.type='button';choice.textContent=segment;choice.onclick=()=>{if(locked)return;if(segment!==task.wrong){evacuationWrong([choice]);return;}sentence.querySelectorAll('button').forEach(button=>button.disabled=true);choice.classList.add('selected');const correction=content.querySelector('.evacuation-correction');correction.innerHTML='<form><label>Correct the selected part:<input type="text" autocomplete="off" placeholder="Type the correction"></label><button type="submit">UNLOCK GATE</button></form>';const form=correction.querySelector('form'),input=form.querySelector('input');form.onsubmit=event=>{event.preventDefault();if(locked)return;if(normalizeTypedAnswer(input.value)===task.correction){sentence.textContent='The gates will open as soon as the pilot gives the signal.';completeEvacuationStation(id,'SECURITY GATE UNLOCKED ✓');}else evacuationWrong([input]);};input.focus();};sentence.append(choice);});return;}const {content}=evacuationTaskShell('Complete both gaps with the correct verb forms.');content.innerHTML='<form class="evacuation-form evacuation-double"><p class="evacuation-sentence"></p><button type="submit">AUTHORIZE LANDING ZONE</button></form>';const form=content.querySelector('form'),sentence=form.querySelector('p');task.parts.forEach((part,index)=>{sentence.append(document.createTextNode(part));if(index<task.answers.length){const input=document.createElement('input');input.type='text';input.autocomplete='off';input.placeholder='Type your answer';input.size=index===0?10:24;input.setAttribute('aria-label',`Final clearance verb form ${index+1}`);sentence.append(input);}});form.onsubmit=event=>{event.preventDefault();if(locked)return;const inputs=[...form.querySelectorAll('input')],correct=inputs.every((input,index)=>normalizeTypedAnswer(input.value)===task.answers[index]);if(correct)completeEvacuationStation(id,'LANDING ZONE CLEARED ✓');else evacuationWrong(inputs.filter((input,index)=>normalizeTypedAnswer(input.value)!==task.answers[index]));};form.querySelector('input').focus();}
function evacuationWrong(controls){controls.forEach(control=>{control.classList.remove('wrong');void control.offsetWidth;control.classList.add('wrong');});audio.sfx('wrong');state.wrongAnswers++;state.streak=0;state.lives=Math.max(0,state.lives-1);state.livesLost++;updateHud();showFeedback(state.lives===0?'WRONG — EMERGENCY RESCUE':'WRONG — TRY AGAIN','bad');const depleted=loseEnergyForWrongAnswer();if(depleted)return;if(state.lives===0){locked=true;document.querySelectorAll('.evacuation-task button,.evacuation-task input').forEach(control=>control.disabled=true);transitionId=setTimeout(launchEmergencyRescue,750);}}
function completeEvacuationStation(id,message){if(locked||evacuationStationComplete(id))return;locked=true;state.game12Completed.push(id);state.gameProgress=state.game12Completed.length;state.correctAnswers++;if(state.lives===3)state.firstAttemptCorrect++;state.streak++;state.maxStreak=Math.max(state.maxStreak,state.streak);state.score+=CONFIG.multipleChoiceScore;audio.sfx('correct');updateHud();document.querySelectorAll('.evacuation-task button,.evacuation-task input').forEach(control=>control.disabled=true);showFeedback(message,'good',READABLE_MESSAGE_DURATION);transitionId=setTimeout(()=>{if(state.game12Completed.length===4)completeEnergyStep(12,showFinalAuthorization);else showEvacuationScene(id);},READABLE_MESSAGE_DURATION);}
function showLandingZoneClearance(){locked=false;state.game12ActiveStation='landing';clearScreen();const stage=document.createElement('div');stage.className='landing-clear-stage';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;stage.innerHTML='<header><h2>CLEAR THE LANDING ZONE</h2><p>Clear the landing zone. Drag all obstacles outside the marked area.</p><output>OBSTACLES: 0/3 CLEARED</output></header><div class="landing-boundary"><span>LANDING ZONE</span></div><div class="landing-obstacles"></div>';const obstacleLayer=stage.querySelector('.landing-obstacles'),starts=[[42,64,-5],[51,72,4],[59,61,-2]];starts.forEach((start,index)=>{const obstacle=document.createElement('img');obstacle.src=ASSETS.interactive.conveyorBox;obstacle.alt=`Landing-zone obstacle ${index+1}`;obstacle.className='landing-obstacle';obstacle.style.left=`${start[0]}%`;obstacle.style.top=`${start[1]}%`;obstacle.style.setProperty('--box-rotation',`${start[2]}deg`);makeLandingObstacleDraggable(obstacle,stage);obstacleLayer.append(obstacle);});screen.append(stage);}
function makeLandingObstacleDraggable(obstacle,stage){let pointerId=null;obstacle.onpointerdown=event=>{if(obstacle.classList.contains('cleared'))return;pointerId=event.pointerId;obstacle.setPointerCapture(pointerId);obstacle.classList.add('dragging');event.preventDefault();};obstacle.onpointermove=event=>{if(event.pointerId!==pointerId)return;const bounds=stage.getBoundingClientRect(),x=Math.max(5,Math.min(95,(event.clientX-bounds.left)/bounds.width*100)),y=Math.max(31,Math.min(94,(event.clientY-bounds.top)/bounds.height*100));obstacle.style.left=`${x}%`;obstacle.style.top=`${y}%`;};const release=event=>{if(event.pointerId!==pointerId)return;pointerId=null;obstacle.classList.remove('dragging');const objectBox=obstacle.getBoundingClientRect(),zoneBox=stage.querySelector('.landing-boundary').getBoundingClientRect(),centerX=objectBox.left+objectBox.width/2,centerY=objectBox.top+objectBox.height/2,inside=centerX>=zoneBox.left&&centerX<=zoneBox.right&&centerY>=zoneBox.top&&centerY<=zoneBox.bottom;if(inside){showFeedback('MOVE THE OBSTACLE OUTSIDE THE LANDING ZONE','info',850);return;}obstacle.classList.add('cleared');obstacle.style.pointerEvents='none';const cleared=stage.querySelectorAll('.landing-obstacle.cleared').length;stage.querySelector('header output').textContent=`OBSTACLES: ${cleared}/3 CLEARED`;if(cleared===3){state.game12ObstaclesCleared=true;locked=true;showFeedback('LANDING ZONE PHYSICALLY CLEAR','good',READABLE_MESSAGE_DURATION);transitionId=setTimeout(()=>showEvacuationTask('landing'),READABLE_MESSAGE_DURATION);}};obstacle.onpointerup=release;obstacle.onpointercancel=release;}
function showFinalAuthorization(){if(state.secrets<5){locked=false;showEvacuationScene();const stage=screen.querySelector('.evacuation-game'),signal=document.createElement('div');signal.className='nightfall-signal-detected';signal.textContent='PROJECT NIGHTFALL SIGNAL DETECTED';stage.append(signal);transitionId=setTimeout(()=>signal.remove(),READABLE_MESSAGE_DURATION);return;}locked=true;showEvacuationScene();locked=true;const stage=screen.querySelector('.evacuation-game'),message=document.createElement('div');stage.classList.add('final-layout');message.className='final-clearance-message';message.textContent='CLEARANCE 100%';stage.append(message);transitionId=setTimeout(()=>{message.textContent='FINAL CLEARANCE COMPLETE ✓';transitionId=setTimeout(()=>{message.textContent='EVACUATION AUTHORIZED';transitionId=setTimeout(()=>startFinalHelicopterArrival(stage,message),READABLE_MESSAGE_DURATION);},READABLE_MESSAGE_DURATION);},READABLE_MESSAGE_DURATION);}
function startFinalHelicopterArrival(stage,message){startHelicopterAmbience(stage);const nightfallReady=preloadImages([ASSETS.nightfallLab,'assets/ui/nightfall_panel.png',...Object.values(NIGHTFALL_COLLECTIBLES).map(item=>item.asset)]),helicopter=document.createElement('img');helicopter.className='evacuation-helicopter';helicopter.src=ASSETS.interactive.transmissionHelicopter;helicopter.alt='Rescue helicopter arriving at the evacuation point';stage.append(helicopter);message.classList.add('arrival-hidden');transitionId=setTimeout(()=>{message.className='final-clearance-message landed-status';message.textContent='HELICOPTER LANDED ✓';transitionId=setTimeout(()=>{message.textContent='EVACUATION COMPLETE';message.classList.add('evacuation-complete');audio.sfx('complete');transitionId=setTimeout(async()=>{await nightfallReady;beginNightfallEndingFlow();},READABLE_MESSAGE_DURATION);},READABLE_MESSAGE_DURATION);},7200);}
function beginNightfallEndingFlow(){stopHelicopterAmbience();if(state.secrets!==5){showNightfallIncomplete();return;}clearScreen();const transition=document.createElement('div');transition.className='nightfall-transition';transition.innerHTML='<div><span>INCOMING CLASSIFIED TRANSMISSION...</span><i aria-hidden="true"></i></div>';screen.append(transition);requestAnimationFrame(()=>transition.classList.add('active'));transitionId=setTimeout(showNightfallTerminal,READABLE_MESSAGE_DURATION);}
function showNightfallIncomplete(){clearScreen();screen.style.backgroundImage=`linear-gradient(#010409d9,#010409ed),url('${ASSETS.evacuationPoint}')`;const panel=document.createElement('section');panel.className='nightfall-incomplete';panel.innerHTML='<strong>PROJECT NIGHTFALL DATA INCOMPLETE</strong><span>5 EVIDENCE ITEMS REQUIRED</span><button type="button">CONTINUE</button>';panel.querySelector('button').onclick=()=>showEvacuationScene();screen.append(panel);}
function createNightfallEvidence(){const evidence=document.createElement('div');evidence.className='nightfall-evidence';Object.entries(NIGHTFALL_COLLECTIBLES).forEach(([id,item])=>{const image=document.createElement('img');image.src=item.asset;image.alt=item.name;image.className=`evidence-${id}`;evidence.append(image);});return evidence;}
function showNightfallTerminal(){clearScreen();updateHud();const stage=document.createElement('div');stage.className='nightfall-stage';stage.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;stage.innerHTML='<header class="nightfall-header"><p>PROJECT NIGHTFALL</p><span>CLASSIFIED // LEVEL 5</span><strong>DECRYPT THE CLASSIFIED FILE</strong></header><section class="nightfall-terminal"><form class="nightfall-form"><div class="nightfall-rows"></div><button type="submit">DECRYPT FILE</button></form><aside class="nightfall-file" data-progress="0"><header><b>PROJECT NIGHTFALL</b><span>ENCRYPTED FILE</span></header><div class="nightfall-file-lines"><i></i><i></i><i></i><i></i></div><div class="nightfall-redactions" aria-hidden="true"><span></span><span></span><span></span><span></span></div></aside><output class="nightfall-progress">DECRYPTION: 0%</output><div class="nightfall-unlock-status" aria-live="polite"></div></section>';const rows=stage.querySelector('.nightfall-rows');NIGHTFALL_DECRYPTION_DATA.forEach((item,index)=>{const row=document.createElement('label');row.className='nightfall-row';row.dataset.index=index;const number=document.createElement('b');number.textContent=String(index+1).padStart(2,'0');const sentence=document.createElement('span');sentence.className='nightfall-sentence';const input=document.createElement('input');input.type='text';input.autocomplete='off';input.size=Math.max(18,item.answer.length+2);input.setAttribute('aria-label',`Nightfall line ${index+1} missing verb form`);sentence.append(document.createTextNode(item.before),input,document.createTextNode(item.after));row.append(number,sentence);rows.append(row);});const form=stage.querySelector('.nightfall-form');form.onsubmit=event=>{event.preventDefault();checkNightfallAnswers(stage);};stage.append(createNightfallEvidence());screen.append(stage);form.querySelector('input').focus();}
function checkNightfallAnswers(stage){const rows=[...stage.querySelectorAll('.nightfall-row')];let newlyCorrect=0;rows.forEach((row,index)=>{const input=row.querySelector('input');if(input.disabled)return;if(normalizeTypedAnswer(input.value)===NIGHTFALL_DECRYPTION_DATA[index].answer){input.disabled=true;row.classList.remove('wrong');row.classList.add('decrypted');newlyCorrect++;}else{row.classList.remove('wrong');void row.offsetWidth;row.classList.add('wrong');}});const completed=rows.filter(row=>row.classList.contains('decrypted')).length,percent=completed*25;stage.querySelector('.nightfall-progress').textContent=`DECRYPTION: ${percent}%`;stage.querySelector('.nightfall-file').dataset.progress=String(percent);if(newlyCorrect)audio.sfx('correct');else audio.sfx('wrong');if(completed===4)completeNightfallDecryption(stage);else rows.find(row=>!row.classList.contains('decrypted'))?.querySelector('input')?.focus();}
function completeNightfallDecryption(stage){const submit=stage.querySelector('.nightfall-form>button');submit.disabled=true;const status=stage.querySelector('.nightfall-unlock-status');status.textContent='DECRYPTION 100%';state.nightfallDecryptionCompleted=true;awardMasterCollectorIfEligible();transitionId=setTimeout(()=>{audio.sfx('nightfallUnlock');status.textContent='CLASSIFIED FILE UNLOCKED';stage.classList.add('file-unlocked');transitionId=setTimeout(showNightfallClassifiedFile,READABLE_MESSAGE_DURATION);},READABLE_MESSAGE_DURATION);}
function showNightfallClassifiedFile(){clearScreen();const stage=document.createElement('div');stage.className='nightfall-stage nightfall-reveal';stage.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;const file=document.createElement('section');file.className='classified-reveal';file.innerHTML='<header><p>PROJECT NIGHTFALL — CLASSIFIED FILE</p><i aria-hidden="true"></i></header><div class="classified-story" aria-live="polite"></div>';const evidence=createNightfallEvidence();evidence.classList.add('classified-evidence');const story=file.querySelector('.classified-story'),lines=['The evidence confirms that Project Nightfall was a hidden network of devices beneath the city.',"The network caused tonight's blackout and the earlier unexplained power failures.","By restoring the city's emergency systems, you helped expose and disable the Nightfall network.",'Power restoration has begun. The city is safe.'];stage.append(evidence,file);screen.append(stage);let lineIndex=0;const typeLine=()=>{const line=document.createElement('p'),text=lines[lineIndex],cursor=document.createElement('b');cursor.className='terminal-cursor';cursor.setAttribute('aria-hidden','true');line.append(cursor);story.append(line);let characterIndex=0;const typeCharacter=()=>{if(characterIndex<text.length){line.insertBefore(document.createTextNode(text[characterIndex++]),cursor);transitionId=setTimeout(typeCharacter,27);return;}cursor.remove();lineIndex++;if(lineIndex<lines.length){transitionId=setTimeout(typeLine,560);return;}const proceed=document.createElement('button');proceed.type='button';proceed.className='classified-continue';proceed.textContent='CONTINUE';proceed.onclick=()=>{audio.sfx('click');showNightfallCaseSolved();};file.append(proceed);requestAnimationFrame(()=>proceed.classList.add('visible'));};typeCharacter();};transitionId=setTimeout(typeLine,700);}
function showNightfallCaseSolved(){clearScreen();const finalReady=preloadImages([ASSETS.evacuationPoint,`${ASSETS.achievementsRoot}/master_collector.png`,'assets/reference/bees_knees_badge.png']),stage=document.createElement('div');stage.className='nightfall-stage nightfall-case-solved';stage.style.backgroundImage=`url('${ASSETS.nightfallLab}')`;const message=document.createElement('section');message.innerHTML='<p>PROJECT NIGHTFALL</p><strong>CASE SOLVED</strong>';stage.append(createNightfallEvidence(),message);screen.append(stage);audio.sfx('complete');transitionId=setTimeout(()=>{stage.classList.add('ending-fade');transitionId=setTimeout(async()=>{await finalReady;showFinalMissionResults();},650);},READABLE_MESSAGE_DURATION);}
function formatMissionTime(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function awardAchievement(id){if(!state.achievements.includes(id))state.achievements.push(id);}
function awardMasterCollectorIfEligible(){const completeEvidence=Object.keys(NIGHTFALL_COLLECTIBLES).every(id=>state.collectedSecrets.includes(id));if(state.nightfallDecryptionCompleted&&state.secrets===5&&completeEvidence)awardAchievement('masterCollector');}
function evaluateFinalAchievements(){const attempts=state.correctAnswers+state.wrongAnswers,accuracy=attempts?Math.round(state.correctAnswers/attempts*100):100;awardAchievement('explorer');if(accuracy>=90)awardAchievement('grammarMaster');awardMasterCollectorIfEligible();if(state.finalElapsedSeconds<=1800)awardAchievement('speedRunner');if(state.maxStreak>=10)awardAchievement('unstoppable');if(state.livesLost===0)awardAchievement('untouchable');}
function showFinalMissionResults(){clearInterval(timerId);state.finalElapsedSeconds=state.finalElapsedSeconds||Math.max(0,Math.floor((Date.now()-state.startedAt)/1000));evaluateFinalAchievements();hud.classList.add('hidden');clearScreen();const attempts=state.correctAnswers+state.wrongAnswers,accuracy=attempts?Math.round(state.correctAnswers/attempts*100):100,missionTime=formatMissionTime(state.finalElapsedSeconds),evidence=`${state.secrets}/5`,rescue=String(state.emergencyRescueCount),stage=document.createElement('div');stage.className='final-results';stage.style.backgroundImage=`url('${ASSETS.evacuationPoint}')`;stage.innerHTML='<section class="final-dashboard"><header class="final-results-heading"><h1>MISSION COMPLETE</h1><h2>PROJECT NIGHTFALL — CASE SOLVED</h2></header><div class="final-stats" aria-label="Final mission statistics"></div><div class="final-results-lower"><section class="final-achievement-report"><h3>ACHIEVEMENTS UNLOCKED</h3><div class="final-achievements"></div></section><section class="survival-report"><h3>SURVIVAL REPORT</h3><dl></dl></section></div><div class="final-actions"><button type="button">PLAY AGAIN</button><a class="branding-badge" href="https://beeskneeseng.ru" target="_blank" rel="noopener noreferrer"><img src="assets/reference/bees_knees_badge.png" alt="Bee\'s Knees English"></a></div></section>';const statValues=[['FINAL SCORE',state.score.toLocaleString()],['TIME',missionTime],['GRAMMAR ACCURACY',`${accuracy}%`],['LIVES REMAINING',String(state.lives)],['SECRETS / EVIDENCE FOUND',evidence],['EMERGENCY RESCUE',rescue]];const stats=stage.querySelector('.final-stats');statValues.forEach(([label,value])=>{const item=document.createElement('p');item.innerHTML='<span></span><strong></strong>';item.querySelector('span').textContent=label;item.querySelector('strong').textContent=value;stats.append(item);});const achievementDefinitions=[['explorer','EXPLORER','explorer.png'],['grammarMaster','GRAMMAR MASTER','grammar_master.png'],['masterCollector','MASTER COLLECTOR','master_collector.png'],['speedRunner','SPEED RUNNER','speed_runner.png'],['unstoppable','UNSTOPPABLE','unstoppable.png'],['untouchable','UNTOUCHABLE','untouchable.png']],achievements=stage.querySelector('.final-achievements');achievementDefinitions.forEach(([id,name,file])=>{const unlocked=state.achievements.includes(id),item=document.createElement('figure');item.className=unlocked?'unlocked':'locked';item.innerHTML=`<img src="${ASSETS.achievementsRoot}/${file}" alt="${name}"><figcaption>${name}</figcaption>${unlocked?'':'<span>LOCKED</span>'}`;achievements.append(item);});const survivalValues=[['Correct Answers',state.correctAnswers.toLocaleString()],['Accuracy',`${accuracy}%`],['Time',missionTime],['Lives Remaining',String(state.lives)],['Evidence Found',evidence],['Emergency Rescue',rescue],['Final Score',state.score.toLocaleString()]],report=stage.querySelector('.survival-report dl');survivalValues.forEach(([label,value])=>{const term=document.createElement('dt'),description=document.createElement('dd');term.textContent=label;description.textContent=value;report.append(term,description);});stage.querySelector('button').onclick=()=>{audio.sfx('click');state.reset();updateHud();showStart();};screen.append(stage);}
const renderFinalResultsWithExternalBranding=showFinalMissionResults;showFinalMissionResults=function(){renderFinalResultsWithExternalBranding();const stage=screen.querySelector('.final-results'),badge=stage?.querySelector('.branding-badge');if(stage&&badge)stage.append(badge);};
const renderEvacuationScene=showEvacuationScene;
showEvacuationScene=function(recent=''){renderEvacuationScene(recent);const stage=screen.querySelector('.evacuation-game');if(!stage)return;const missing=Object.keys(NIGHTFALL_COLLECTIBLES).filter(id=>!state.collectedSecrets.includes(id));missing.forEach((id,index)=>addNightfallCollectible(stage,id,`nightfall-fallback game12-secret game12-secret-${index+1}`));};
function resumeEvacuationTask(){if(state.game12ActiveStation==='landing'&&!state.game12ObstaclesCleared)showLandingZoneClearance();else showEvacuationTask(state.game12ActiveStation||'passengers');}
audioToggle.addEventListener('click',()=>{if(helicopterAmbience)helicopterAmbience.volume=audio.muted?0:.03;});
