function completeRoute(route){const key={serviceTunnels:'serviceTunnelsCompleted',cityStreets:'cityStreetsCompleted',mainBridge:'mainBridgeCompleted'}[route];if(key)state[key]=true;state.selectedRoute=null;showRouteSelection();}
function selectRescueQuestions(){const excluded=new Set(previousRescueQuestionIds),candidates=RESCUE_QUESTION_POOL.filter(question=>!excluded.has(question.id));for(let index=candidates.length-1;index>0;index--){const randomIndex=Math.floor(Math.random()*(index+1));[candidates[index],candidates[randomIndex]]=[candidates[randomIndex],candidates[index]];}rescueQuestions=candidates.slice(0,5);previousRescueQuestionIds=rescueQuestions.map(question=>question.id);}
async function launchEmergencyRescue(){await preloadImage(ASSETS.emergencyRescue);selectRescueQuestions();state.rescueIndex=0;state.rescueCorrect=0;renderRescueQuestion();}
function renderRescueQuestion(){clearScreen();const rescue=rescueQuestions[state.rescueIndex];const stage=document.createElement('div');stage.className='rescue-stage';const content=document.createElement('div');content.className='rescue-content';content.innerHTML=`<h2>EMERGENCY RESCUE</h2><p class="rescue-instruction">Choose the correct answer. Get 3 out of 5 to continue.</p><p class="rescue-progress">${state.rescueIndex+1} / 5</p><p class="rescue-sentence"></p><div class="rescue-answers"></div>`;content.querySelector('.rescue-sentence').textContent=rescue.sentence;const answers=content.querySelector('.rescue-answers');rescue.options.forEach(option=>{const choice=document.createElement('button');choice.type='button';choice.textContent=option;choice.onclick=()=>answerRescue(choice,option);answers.append(choice);});stage.append(content);screen.append(stage);}
function answerRescue(buttonElement,choice){document.querySelectorAll('.rescue-answers button').forEach(button=>button.disabled=true);const correct=choice===rescueQuestions[state.rescueIndex].answer;buttonElement.classList.add(correct?'correct':'wrong');if(correct){state.rescueCorrect++;audio.sfx('correct');}else audio.sfx('wrong');transitionId=setTimeout(()=>{state.rescueIndex++;if(state.rescueIndex<rescueQuestions.length)renderRescueQuestion();else finishEmergencyRescue();},650);}
function finishEmergencyRescue(){clearScreen();const result=document.createElement('div');result.className='rescue-result';if(state.rescueCorrect>=3){state.emergencyRescueCount++;result.innerHTML=`<h2>RESCUE SUCCESSFUL</h2><p>${state.rescueCorrect}/5 CORRECT</p>`;screen.append(result);if(state.game===12){transitionId=setTimeout(resumeEvacuationTask,READABLE_MESSAGE_DURATION);return;}if(state.game===11){transitionId=setTimeout(showEmergencyTransmissionPacket,READABLE_MESSAGE_DURATION);return;}if(state.game===10){transitionId=setTimeout(showCheckpointStage,READABLE_MESSAGE_DURATION);return;}if(state.game===9){transitionId=setTimeout(showEmergencyRadioTransmission,READABLE_MESSAGE_DURATION);return;}if(state.game===8){transitionId=setTimeout(showTrainTimelineTask,READABLE_MESSAGE_DURATION);return;}if(state.game===7){transitionId=setTimeout(showRooftopSignalQuestion,READABLE_MESSAGE_DURATION);return;}if(state.game===6){transitionId=setTimeout(showBridgeWarningQuestion,READABLE_MESSAGE_DURATION);return;}if(state.game===5){transitionId=setTimeout(showErrorDetectorQuestion,READABLE_MESSAGE_DURATION);return;}if(state.game===3){state.gameProgress++;transitionId=setTimeout(()=>awardSupplyItem(SUPPLY_SEARCH_DATA[state.questionIndex]),READABLE_MESSAGE_DURATION);return;}if(state.game===2||state.game===4)state.gameProgress++;state.questionIndex++;transitionId=setTimeout(()=>{if(state.game===2?state.questionIndex<4:state.questionIndex<currentGrammarData().length)showQuestion();else if(state.game===1)showGameOneComplete();else if(state.game===2)showGameTwoComplete();else showServiceTunnelsComplete();},READABLE_MESSAGE_DURATION);}else{result.innerHTML=`<h2>MISSION FAILED / RESCUE FAILED</h2><p>${state.rescueCorrect}/5 CORRECT</p>`;const retry=document.createElement('button');retry.type='button';retry.textContent='RETRY EMERGENCY RESCUE';retry.onclick=()=>{audio.sfx('click');launchEmergencyRescue();};result.append(retry);screen.append(result);}}
function renderAudioPanel(){const panel=document.createElement('section');panel.className='audio-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Audio settings');panel.innerHTML=`<h2>AUDIO</h2><label><span>MUSIC</span><input id="music-volume" type="range" min="0" max="1" step=".05" value="${audio.musicVolume}"><output>${Math.round(audio.musicVolume*100)}%</output></label><label><span>SFX</span><input id="sfx-volume" type="range" min="0" max="1" step=".05" value="${audio.sfxVolume}"><output>${Math.round(audio.sfxVolume*100)}%</output></label><button id="mute-audio" type="button">${audio.muted?'UNMUTE':'MUTE'}</button>`;modalRoot.replaceChildren(panel);const music=panel.querySelector('#music-volume'),sfx=panel.querySelector('#sfx-volume');music.oninput=()=>{audio.setMusicVolume(music.value);music.nextElementSibling.textContent=`${Math.round(music.value*100)}%`;};sfx.oninput=()=>{audio.setSfxVolume(sfx.value);sfx.nextElementSibling.textContent=`${Math.round(sfx.value*100)}%`;};panel.querySelector('#mute-audio').onclick=event=>{event.stopPropagation();event.currentTarget.textContent=audio.toggleMute()?'UNMUTE':'MUTE';updateAudioIcon();};panel.onclick=event=>event.stopPropagation();return panel;}
function toggleAudioPanel(forceOpen=false){const open=modalRoot.firstElementChild;if(open&&!forceOpen){closeAudioPanel();return;}if(!open)renderAudioPanel();audioToggle.setAttribute('aria-expanded','true');}
