function showEnergyRecovery(){locked=true;const recoveryItems=[['Water Bottle',ASSETS.items.waterBottle],['Chocolate Bar',ASSETS.items.chocolateBar],['First Aid Kit',ASSETS.items.firstAidKit],['Batteries',ASSETS.items.batteries]].filter(([name])=>state.inventory.includes(name)&&!state.usedEnergySupplies.includes(name));const panel=document.createElement('section');panel.className='energy-recovery';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Energy depleted');panel.innerHTML='<h2>ENERGY DEPLETED</h2><p>Choose a supply to restore your energy.</p><div class="energy-supplies"></div><output aria-live="polite"></output>';const supplies=panel.querySelector('.energy-supplies');recoveryItems.forEach(([name,asset])=>{const use=document.createElement('button');use.type='button';use.innerHTML=`<img src="${asset}" alt=""><span>${name.toUpperCase()}</span>`;use.onclick=event=>{event.stopPropagation();useEnergySupply(name,use);};supplies.append(use);});if(!recoveryItems.length){const empty=document.createElement('strong');empty.className='energy-empty';empty.textContent='NO ENERGY SUPPLIES AVAILABLE';supplies.append(empty);}panel.onclick=event=>event.stopPropagation();modalRoot.replaceChildren(panel);}
function useEnergySupply(name,buttonElement){const itemIndex=state.inventory.indexOf(name);if(itemIndex<0||state.usedEnergySupplies.includes(name))return;const panel=buttonElement.closest('.energy-recovery');panel.querySelectorAll('button').forEach(button=>button.disabled=true);buttonElement.classList.add('selected');state.inventory.splice(itemIndex,1);state.usedEnergySupplies.push(name);state.energy=CONFIG.maxEnergy;updateHud();audio.sfx('itemPickup');panel.classList.add('restored');panel.querySelector('output').textContent='ENERGY RESTORED — 100%';const continuation=energyRecoveryContinuation;energyRecoveryContinuation=null;transitionId=setTimeout(()=>{modalRoot.replaceChildren();locked=false;if(continuation)continuation();},READABLE_MESSAGE_DURATION);}
