audioToggle.onclick=event=>{event.stopPropagation();audio.unlock();toggleAudioPanel();};document.addEventListener('pointerdown',event=>{if(modalRoot.firstElementChild&&!modalRoot.querySelector('.energy-recovery')&&!modalRoot.contains(event.target)&&event.target!==audioToggle)closeAudioPanel();});
document.querySelector('#backpack').onclick=event=>{event.stopPropagation();audio.sfx('inventory');toggleInventoryPanel();};
