function startNightfallEvidencePreviewDevMode(){if(!LOCAL_DEV_HOSTS.has(location.hostname)||!/^nightfall-[1-5]$/.test(DEV_REQUEST||''))return false;const count=Number(DEV_REQUEST.slice(-1));state.reset();Object.assign(state,{game:[1,2,4,6,10][count-1],score:1000,energy:75,lives:3,collectedSecrets:NIGHTFALL_COLLECTIBLE_ORDER.slice(0,count),secrets:count,inventory:SUPPLY_SEARCH_DATA.map(item=>item.reward),serviceTunnelsCompleted:count>=4,cityStreetsCompleted:count>=4,mainBridgeCompleted:count>=5,questionIndex:0,gameProgress:0,startedAt:Date.now()});preloadFirstMissionAssets();updateHud();armDevAudioUnlock();if(count===1)showHome();else{hud.classList.remove('hidden');if(count===2)showStreetGridQuestion();else if(count===3)showTunnelDrive();else if(count===4)showBridgeWarningQuestion();else showCheckpointStage();}showNightfallNotice(count===5,true);return true;}
function startClassifiedRevealDevMode(){if(!LOCAL_DEV_HOSTS.has(location.hostname)||DEV_REQUEST!=='nightfall-reveal')return false;state.reset();Object.assign(state,{score:4800,energy:75,lives:3,secrets:5,collectedSecrets:[...NIGHTFALL_COLLECTIBLE_ORDER],startedAt:Date.now()-754000});hud.classList.remove('hidden');updateHud();armDevAudioUnlock();showNightfallClassifiedFile();return true;}
function startNarrativeDebugMode(){if(!LOCAL_DEV_HOSTS.has(location.hostname))return false;const targets=new Set(['rules','home-bedroom','phone-success','blackout-street','supply-search','evacuation-routes','service-tunnels-intro','city-streets-intro','main-bridge-intro','nightfall-1','nightfall-2','nightfall-3','nightfall-4','nightfall-5','rooftop-complete','train-intro','train-complete','emergency-radio-intro','checkpoint-intro','rescue-helicopter','evacuation-point','nightfall-reveal','mission-complete']);if(!targets.has(DEV_REQUEST))return false;state.reset();Object.assign(state,{score:4800,energy:75,lives:3,startedAt:Date.now()-754000,inventory:SUPPLY_SEARCH_DATA.map(item=>item.reward)});hud.classList.toggle('hidden',DEV_REQUEST==='rules'||DEV_REQUEST==='mission-complete');updateHud();armDevAudioUnlock();const showStatic=render=>{render();clearTimeout(transitionId);transitionId=0;};if(DEV_REQUEST==='rules')showHow();else if(DEV_REQUEST==='home-bedroom')showHome();else if(DEV_REQUEST==='phone-success')showPhoneSuccessDevScreen();else if(DEV_REQUEST==='blackout-street')showStatic(showBlackoutStreet);else if(DEV_REQUEST==='supply-search')showStatic(showSupplySearchIntro);else if(DEV_REQUEST==='evacuation-routes')showRouteSelection();else if(DEV_REQUEST==='service-tunnels-intro')showStatic(showServiceTunnelsIntro);else if(DEV_REQUEST==='city-streets-intro'){state.serviceTunnelsCompleted=true;showStatic(showCityStreetsIntro);}else if(DEV_REQUEST==='main-bridge-intro'){state.serviceTunnelsCompleted=true;state.cityStreetsCompleted=true;showStatic(showMainBridgeIntro);}else if(DEV_REQUEST.startsWith('nightfall-')){const count=Number(DEV_REQUEST.slice(-1));state.collectedSecrets=NIGHTFALL_COLLECTIBLE_ORDER.slice(0,count);state.secrets=count;showHome();showNightfallNotice(count===5,true);}else if(DEV_REQUEST==='rooftop-complete'){state.mainBridgeCompleted=true;showStatic(showRooftopSignalComplete);}else if(DEV_REQUEST==='train-intro'){state.mainBridgeCompleted=true;showStatic(showGameEightLocked);}else if(DEV_REQUEST==='train-complete'){state.mainBridgeCompleted=true;showStatic(showTrainTimelineComplete);}else if(DEV_REQUEST==='emergency-radio-intro'){state.mainBridgeCompleted=true;showStatic(showGameNineLocked);}else if(DEV_REQUEST==='checkpoint-intro'){state.mainBridgeCompleted=true;showStatic(showGameTenLocked);}else if(DEV_REQUEST==='rescue-helicopter'){state.mainBridgeCompleted=true;showStatic(showGameElevenLocked);}else if(DEV_REQUEST==='evacuation-point'){state.mainBridgeCompleted=true;showStatic(showGameTwelveLocked);}else if(DEV_REQUEST==='nightfall-reveal'){state.secrets=5;state.collectedSecrets=[...NIGHTFALL_COLLECTIBLE_ORDER];showNightfallClassifiedFile();}else{Object.assign(state,{secrets:5,collectedSecrets:[...NIGHTFALL_COLLECTIBLE_ORDER],achievements:['masterCollector'],finalElapsedSeconds:754});showFinalMissionResults();}return true;}
const renderClassifiedRevealDevMode=startClassifiedRevealDevMode;startClassifiedRevealDevMode=function(){if(DEV_REQUEST&&LOCAL_DEV_HOSTS.has(location.hostname))preloadFirstMissionAssets();return renderClassifiedRevealDevMode();};
const renderNarrativeDebugMode=startNarrativeDebugMode;startNarrativeDebugMode=function(){if(DEV_REQUEST&&LOCAL_DEV_HOSTS.has(location.hostname))preloadFirstMissionAssets();return renderNarrativeDebugMode();};
function startGameThreeIntroDevMode(){if(!LOCAL_DEV_HOSTS.has(location.hostname)||DEV_REQUEST!=='game3-intro')return false;state.reset();Object.assign(state,{game:2,score:1000,energy:75,lives:3,startedAt:Date.now()});hud.classList.remove('hidden');updateHud();startTimer();armDevAudioUnlock();showSupplySearchIntro();return true;}
function startNightfallDevMode(){if(!LOCAL_DEV_HOSTS.has(location.hostname)||!['nightfall','ending'].includes(DEV_REQUEST))return false;state.reset();Object.assign(state,{game:12,score:4800,energy:75,lives:3,secrets:5,collectedSecrets:Object.keys(NIGHTFALL_COLLECTIBLES),inventory:SUPPLY_SEARCH_DATA.map(item=>item.reward),serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:true,game12Completed:['passengers','lights','gate','landing'],game12ObstaclesCleared:true,startedAt:Date.now()-754000});hud.classList.remove('hidden');updateHud();startTimer();armDevAudioUnlock();if(DEV_REQUEST==='ending'){state.achievements=['masterCollector'];showFinalMissionResults();}else showNightfallTerminal();return true;}
function startDevMode(){if(!DEV_TARGET||!LOCAL_DEV_HOSTS.has(location.hostname))return false;const targets=new Set(['home','phone-memory','game1','street','game2','game3','routes','service-tunnels','city-streets','routes-after-city','game6','game7','game8','game9','game10','game11','game12','rescue']);if(!targets.has(DEV_TARGET))return false;const energyValue=new URLSearchParams(location.search).get('energy'),parsedEnergy=Number(energyValue),devEnergy=energyValue!==null&&energyValue.trim()!==''&&Number.isFinite(parsedEnergy)?Math.max(0,Math.min(CONFIG.maxEnergy,parsedEnergy)):75;state.reset();Object.assign(state,{score:1000,energy:devEnergy,lives:3,secrets:0,startedAt:Date.now()});const devSecretHistory={game2:['medallion'],'service-tunnels':['medallion','usb'],game6:['medallion','usb','processor'],game10:['medallion','usb','processor','fieldNotes']}[DEV_TARGET]||[];state.collectedSecrets=[...devSecretHistory];state.secrets=state.collectedSecrets.length;if(['routes','service-tunnels','city-streets','routes-after-city','game6','game7','game8','game9','game10','game11','game12'].includes(DEV_TARGET))state.inventory=SUPPLY_SEARCH_DATA.map(item=>item.reward);hud.classList.remove('hidden');updateHud();startTimer();armDevAudioUnlock();if(DEV_TARGET==='home')showHome();else if(DEV_TARGET==='phone-memory')showPhoneMemory();else if(DEV_TARGET==='game1'){state.game=1;showQuestion();}else if(DEV_TARGET==='street')showBlackoutStreet();else if(DEV_TARGET==='game2'){state.game=2;state.questionIndex=0;state.gameProgress=0;showQuestion();}else if(DEV_TARGET==='game3'){state.game=3;state.questionIndex=0;state.gameProgress=0;showQuestion();}else if(DEV_TARGET==='routes')showRouteSelection();else if(DEV_TARGET==='service-tunnels'){state.game=4;state.questionIndex=0;state.gameProgress=0;state.serviceTunnelsCompleted=false;showQuestion();}else if(DEV_TARGET==='city-streets'){state.game=5;state.questionIndex=0;state.gameProgress=0;state.serviceTunnelsCompleted=true;state.cityStreetsCompleted=false;showErrorDetectorQuestion();}else if(DEV_TARGET==='routes-after-city'){state.serviceTunnelsCompleted=true;state.cityStreetsCompleted=true;state.mainBridgeCompleted=false;showRouteSelection();}else if(DEV_TARGET==='game6'){Object.assign(state,{game:6,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:false,selectedRoute:'mainBridge'});showBridgeWarningQuestion();}else if(DEV_TARGET==='game7'){Object.assign(state,{game:7,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:false,selectedRoute:'mainBridge'});showRooftopSignalQuestion();}else if(DEV_TARGET==='game8'){Object.assign(state,{game:8,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:true,selectedRoute:null});showTrainTimelineTask();}else if(DEV_TARGET==='game9'){Object.assign(state,{game:9,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:true,selectedRoute:null});showEmergencyRadioTransmission();}else if(DEV_TARGET==='game10'){Object.assign(state,{game:10,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:true,selectedRoute:null});showCheckpointStage();}else if(DEV_TARGET==='game11'){Object.assign(state,{game:11,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:true,selectedRoute:null});showEmergencyTransmissionPacket();}else if(DEV_TARGET==='game12'){Object.assign(state,{game:12,questionIndex:0,gameProgress:0,serviceTunnelsCompleted:true,cityStreetsCompleted:true,mainBridgeCompleted:true,selectedRoute:null,game12Completed:[],game12ActiveStation:null,game12ObstaclesCleared:false});showEvacuationScene();}else{state.game=1;state.questionIndex=0;launchEmergencyRescue();}return true;}
async function initialLoad(){const required=[ASSETS.start,ASSETS.how];let done=0;const bar=document.querySelector('#load-bar'),value=document.querySelector('#load-value');await Promise.all(required.map(src=>preloadImage(src).then(()=>{done++;const percent=Math.round(done/required.length*100);bar.style.width=`${percent}%`;value.textContent=`${percent}%`;})));setTimeout(()=>{document.querySelector('#loading').classList.add('hidden');updateAudioIcon();if(!startFinalResultsPreviewDevMode()&&!startNightfallEvidencePreviewDevMode()&&!startClassifiedRevealDevMode()&&!startNarrativeDebugMode()&&!startSecretFallbackDevMode()&&!startGameThreeIntroDevMode()&&!startNightfallDevMode()&&!startDevMode())showStart();},250);}
initialLoad();
